function arrow(x1,y1,x2,y2,color='#188eb2',label=''){return `<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${color}" stroke-width="3"/><path d="M-9,-5 L0,0 L-9,5" fill="none" stroke="${color}" stroke-width="3" transform="translate(${x2} ${y2}) rotate(${Math.atan2(y2-y1,x2-x1)*180/Math.PI})"/>${label?`<text x="${x2+7}" y="${y2-8}" fill="${color}" font-size="15">${label}</text>`:''}`}
function mini(type,u=1,fig={}){let draw=''; const phi=(fig.angle||0)*Math.PI/180;
 if(type==='compass')draw=`<path d="M70 100H330M200 20V180" stroke="#bbb"/><circle cx="200" cy="100" r="4" fill="#222"/><text x="195" y="15">N</text><text x="195" y="198">S</text><text x="340" y="105">E</text><text x="50" y="105">W</text>`;
 else if(type==='normal')draw=`<path d="M50 160H350" stroke="#333"/><rect x="170" y="110" width="60" height="50" fill="#e2edf0" stroke="#222"/>${arrow(185,30,185,105,'#d98735','P')}${arrow(215,100,215,40,'#a17bdb','U')}`;
 else if(type==='fbd')draw=`<rect x="170" y="75" width="60" height="50" rx="4" fill="#d5eaf0" stroke="#188eb2" stroke-width="2"/>${arrow(200,75,200,15,'#188eb2','N')}${arrow(200,125,200,185,'#d98735','mg')}${arrow(170,100,80,100,'#a17bdb','f')}${arrow(230,100,230+90*Math.cos(phi),100+(fig.down?1:-1)*90*Math.sin(phi),'#24786b','F')}`;
 else if(type==='incline')draw=`<path d="M90 50L340 175H90Z" fill="#f1f3ee" stroke="#223333" stroke-width="2"/><circle cx="91" cy="42" r="19" fill="white" stroke="#223333" stroke-width="2"/><path d="M72 42V125M100 27L221 89" fill="none" stroke="#a17bdb" stroke-width="3"/><rect x="53" y="125" width="39" height="46" fill="#d5eaf0" stroke="#188eb2" stroke-width="2"/><rect x="202" y="78" width="48" height="40" transform="rotate(26 226 98)" fill="#d5eaf0" stroke="#188eb2" stroke-width="2"/><text x="61" y="153">m₁</text><text x="214" y="102">m₂</text>`;
 else if(type==='pulley')draw=`<circle cx="200" cy="45" r="30" fill="#edf1eb" stroke="#222"/><path d="M170 45V130M230 45V90" stroke="#a17bdb" stroke-width="3"/><rect x="145" y="130" width="50" height="50" fill="#d5eaf0" stroke="#188eb2"/><rect x="205" y="90" width="50" height="40" fill="#d5eaf0" stroke="#188eb2"/><text x="154" y="160">m₁</text><text x="214" y="115">m₂</text>`;
 else if(type==='vector')draw=`<path d="M50 170H350M50 170V20" fill="none" stroke="#65766d"/>${arrow(50,170,285,40,'#188eb2','V')}<path d="M50 170H285V40" fill="none" stroke="#a17bdb" stroke-width="2" stroke-dasharray="6 5"/><text x="145" y="192" fill="#d98735">V cosθ</text><text x="295" y="110" fill="#a17bdb">V sinθ</text>`;
 else if(type==='projectile'||u===2)draw=`<path d="M30 170H370" stroke="#8c9c90"/><path d="M40 165Q200 -105 360 165" fill="none" stroke="#188eb2" stroke-width="3" stroke-dasharray="6 5"/><circle cx="200" cy="30" r="9" fill="#188eb2"/>${arrow(200,30,270,30,'#a17bdb','vₓ')}${arrow(200,45,200,105,'#d98735','g')}`;
 else draw=`<path d="M45 15V175M45 100H365" fill="none" stroke="#65766d"/><path d="M60 ${type==='vt-rise'?80:25}L${type==='vt-rise'?350:200} ${type==='vt-rise'?25:100}" stroke="#188eb2" stroke-width="3"/>${type==='vt-rise'?'':`<path d="M200 100L350 175" stroke="#d98735" stroke-width="3"/><path d="M60 25L200 100H60Z" fill="#188eb2" opacity=".13"/><path d="M200 100L350 175V100Z" fill="#d98735" opacity=".15"/>`}<text x="20" y="24">v</text><text x="360" y="122">t</text>`;
 return `<svg viewBox="0 0 400 205" role="img" aria-label="${esc(type)}" style="font-family:inherit">${draw}</svg>`;
}
