function highlightReading(value,ensureDefinition=false){
 const text=tr(value),phrases=[...READING_HIGHLIGHTS[state.lang]].sort((a,b)=>b.length-a.length);
 const matches=[];
 for(const phrase of phrases){const start=text.indexOf(phrase);if(start<0)continue;const end=start+phrase.length;if(matches.some(m=>start<m.end&&end>m.start))continue;matches.push({start,end});}
 if(!matches.length&&ensureDefinition){const end=text.indexOf('. ');matches.push({start:0,end:end>=0?end+1:text.length});}
 matches.sort((a,b)=>a.start-b.start);
 let html='',cursor=0;
 for(const m of matches.slice(0,3)){html+=esc(text.slice(cursor,m.start))+'<mark class="key-highlight" style="background-color:#ffe16a;color:#172d24;font-weight:700;padding:2px 3px;border-radius:3px;box-decoration-break:clone;-webkit-box-decoration-break:clone">'+esc(text.slice(m.start,m.end))+'</mark>';cursor=m.end;}
 return html+esc(text.slice(cursor));
}
function learn(){
 const list=LESSONS.filter(l=>l.u===state.unit),chapters=READING_CHAPTERS.filter(c=>c.u===state.unit);
 return `<div class="eyebrow">LEARN / UNIT 0${state.unit}</div><h1>${tr(UNITS[state.unit-1].title)}</h1><p class="muted">${L('한 유닛을 한 페이지에서 이어서 읽어요. 아래 목차로 이동하거나 처음부터 천천히 내려가세요.','Read each unit as one continuous page. Use the contents to jump ahead, or take your time from the beginning.')}</p>${unitTabs(state.unit)}<div class="reading-toc"><span class="eyebrow">${L('이 유닛의 흐름','IN THIS UNIT')}</span>${chapters.map((c,i)=>`<a href="#reading-${state.unit}-${i}">${i+1}. ${tr(c.title)}</a>`).join('')}</div><p class="highlight-guide">${L('노란 강조: 핵심 개념과 적용 조건 · 초록 상자: 공식 · 주황 표시: 헷갈리기 쉬운 점','Yellow: key ideas and assumptions · Green: formulas · Amber: common pitfalls')}</p><div class="reading lesson">${chapters.map((c,i)=>`<article class="reading-chapter" id="reading-${state.unit}-${i}"><div class="eyebrow">0${i+1} / 03</div><h2>${tr(c.title)}</h2>${c.paragraphs.map(p=>`<p class="reading-prose">${highlightReading(p)}</p>`).join('')}<p class="reading-bridge">${tr(c.bridge)}</p>${c.items.map((j,k)=>{const item=list[j];return `<section class="reading-concept" id="concept-${item.id}"><h3>${tr(item.title)}</h3><p>${highlightReading(item.body,true)}</p>${item.img&&c.items.findIndex(n=>list[n].img===item.img)===k?`<figure><img src="images/diagram-${item.img}.png" alt="${esc(tr(item.title))}" loading="lazy"><figcaption>${tr(item.title)}</figcaption></figure>`:''}<div class="formula">${esc(item.formula)}</div><p class="reading-example"><strong>${L('예를 들어','For example')}</strong> — ${highlightReading(item.example)}</p><p class="reading-caution"><strong>${L('여기서 주의할 점은','Keep in mind')}</strong> ${highlightReading(item.note)}</p></section>`}).join('')}<div class="row reading-actions"><button data-chapter-done="${i}" class="${c.items.every(j=>state.done[list[j].id])?'active':'primary'}">${c.items.every(j=>state.done[list[j].id])?L('이 부분 학습 완료 ✓','Section completed ✓'):L('이 부분 이해했어요 ✓','Mark section understood ✓')}</button><button data-nav="lab">${L('실험실에서 확인하기','Explore in the lab')} ↗</button>${i<2?`<a href="#reading-${state.unit}-${i+1}">${L('이어서 읽기','Keep reading')} ↓</a>`:''}</div></article>`).join('')}${state.unit===3?`<div class="card checklist"><h3>Incline + Pulley FRQ Checklist</h3><span id="check-count">${Object.values(state.checks).filter(Boolean).length}/7</span>${CHECKLIST.map((s,i)=>`<label><input type="checkbox" data-check="${i}" ${state.checks[i]?'checked':''}>${i+1}. ${tr(s)}</label>`).join('')}<button id="reset-checks">${L('체크 초기화','Reset checklist')}</button></div>`:''}<div class="banner"><div><h3>${L('이제 직접 적용해 볼까요?','Ready to apply what you read?')}</h3><p>${L('개념을 읽고, 시뮬레이션에서 확인한 뒤 문제로 연습해요.','Read the idea, explore it in the lab, then practice with questions.')}</p></div><button data-nav="practice">${L('문제 풀기','Practice')} →</button></div></div>`;
}
function range(id,label,min,max,step,value,unit){return `<div><label for="${id}">${label}<output id="${id}-out">${value} ${unit}</output></label><input id="${id}" data-param="${id}" type="range" min="${min}" max="${max}" step="${step}" value="${value}" aria-label="${esc(label)}"></div>`}
function labPage(){lab.unit=state.unit;lab.playing=false;if(state.unit===1)lab.duration=lab.duration1||8;lab.t=Math.min(lab.t,lab.duration);return `<div class="eyebrow">EXPLORE / THE MOTION LAB</div><h1>${L('움직임과 그래프를 한눈에.','Motion and graphs, together.')}</h1><p class="muted">${L('값을 바꾸고 예측해 보세요. 재생하거나 시간을 직접 움직여 확인하세요.','Change a value, make a prediction, then press play or scrub through time.')}</p>${unitTabs(state.unit)}<div class="lab"><div class="control"><h3>${L('실험 조건','Set the scene')}</h3>${state.unit===1?`<div><label for="preset">${L('예시','Preset')}</label><select id="preset"><option value="turn">${L('방향 전환 · +8 m / −8 m','Reversal · +8 m / −8 m')}</option><option value="constant">${L('등속 운동','Constant velocity')}</option><option value="speedup">${L('음의 방향으로 빨라짐','Speeding up to the left')}</option></select></div>${range('x0',L('초기 위치','Initial position'),-10,10,1,lab.x0,'m')}${range('v0',L('초기 속도','Initial velocity'),-10,10,.5,lab.v0,'m/s')}${range('a',L('가속도','Acceleration'),-10,10,.5,lab.a,'m/s²')}<p class="caption">${L('일정한 가속도, 마찰·충돌 없는 1차원 모델. 자유낙하는 2차원 실험실에서 90° 발사로 확인하세요.','Constant acceleration; no friction or collisions. Explore vertical throws at 90° in Unit 2.')}</p>`:state.unit===2?`${range('speed',L('초기 속력','Launch speed'),1,30,.5,lab.speed,'m/s')}${range('angle',L('발사각','Launch angle'),0,90,1,lab.angle,'°')}${range('height',L('초기 높이','Launch height'),0,20,.5,lab.height,'m')}<p class="caption">g = 9.8 m/s²<br>${L('공기저항 없음. 지면 도달 시 정지 표시. 모든 그래프는 동일한 시간을 공유해요.','No air resistance. Playback stops at ground contact. All graphs share the same time.')}</p>`:`${range('m1',L('매달린 질량 m₁','Hanging mass m₁'),1,20,1,lab.m1,'kg')}${range('m2',L('경사면 질량 m₂','Incline mass m₂'),1,20,1,lab.m2,'kg')}${range('theta',L('경사각','Incline angle'),10,60,1,lab.theta,'°')}${range('fa',L('아래로 추가 힘 F_A','Extra downward F_A'),0,100,5,lab.fa,'N')}${range('mus','μ_s',0,1.5,.05,lab.mus,'')}${range('muk','μ_k',0,1,.05,lab.muk,'')}<div><label for="mode">${L('현재 상태','Current state')}</label><select id="mode"><option value="rest">${L('정지 가능성 판정','Test rest equilibrium')}</option><option value="up">${L('m₂가 위로 미끄러짐','m₂ sliding uphill')}</option><option value="down">${L('m₂가 아래로 미끄러짐','m₂ sliding downhill')}</option></select></div><p class="caption">${L('이상적인 줄·도르래, g = 9.8. 이 실험실은 힘과 순간 가속도를 비교하는 정적 모델이에요.','Ideal rope and pulley, g = 9.8. This lab compares forces and instantaneous acceleration; it is a static force model.')}</p>`}</div><div><div id="lab-display"></div>${state.unit!==3?`<div class="card" style="margin-top:14px;padding:16px"><div class="row"><button class="primary" id="play">▶ ${L('재생','Play')}</button><button id="reset-time">↺ ${L('처음으로','Reset')}</button><label for="time" id="time-label">t = 0.00 s</label></div><input id="time" type="range" min="0" max="${lab.duration}" step="0.01" value="0" style="width:100%;accent-color:var(--green);margin-top:12px" aria-label="${L('시간','Time')}"></div><p class="caption">${L('그래프를 클릭해도 같은 순간으로 이동해요. 점선은 같은 시간, 짧은 접선은 순간 기울기예요.','Click any graph to select the same instant. Dashed lines mark shared time; short tangent lines show instantaneous slope.')}</p>`:''}</div></div>`}
function chart(title,unit,fn,T,t,color,caption,area=false,tangent=false){T=Math.max(T,.01);let values=Array.from({length:101},(_,i)=>fn(T*i/100)),lo=Math.min(0,...values),hi=Math.max(0,...values);if(hi-lo<1){hi+=1;lo-=1}let pad=(hi-lo)*.15;hi+=pad;lo-=pad;const X=s=>38+s/T*235,Y=v=>158-(v-lo)/(hi-lo)*128;
 let points=values.map((v,i)=>`${X(T*i/100)},${Y(v)}`).join(' '),fill='';
 if(area){for(let i=0;i<100;i++){let ta=T*i/100,tb=Math.min(t,T*(i+1)/100);if(ta>=t)break;let va=fn(ta),vb=fn(tb);let segments=[[ta,va,tb,vb]];if(va*vb<0){let tz=ta+(tb-ta)*(-va)/(vb-va);segments=[[ta,va,tz,0],[tz,0,tb,vb]]}for(let [s1,y1,s2,y2] of segments)fill+=`<path d="M${X(s1)} ${Y(0)} L${X(s1)} ${Y(y1)} L${X(s2)} ${Y(y2)} L${X(s2)} ${Y(0)}Z" fill="${(y1+y2)>=0?'#188eb2':'#d98735'}" opacity=".22"/>`;}}
 let tangentLine='';if(tangent){let eps=.001,d=(fn(t+eps)-fn(t-eps))/(2*eps),dt=T*.09;tangentLine=`<path d="M${X(Math.max(0,t-dt))} ${Y(fn(t)+d*(Math.max(0,t-dt)-t))} L${X(Math.min(T,t+dt))} ${Y(fn(t)+d*(Math.min(T,t+dt)-t))}" stroke="#d98735" stroke-width="2"/>`;}
 return `<div class="graph"><strong>${title} <small style="display:inline">(${unit})</small></strong><svg viewBox="0 0 300 190" data-graph-time="${T}" role="img" aria-label="${esc(title+' '+caption)}" style="cursor:crosshair"><path d="M38 25V158H273" fill="none" stroke="#cad4c8"/><path d="M38 ${Y(0)}H273" stroke="#a6b6a0"/><path d="M38 ${Y(hi-pad)}H273M38 ${Y(lo+pad)}H273" stroke="#edf1ea"/>${fill}<polyline points="${points}" fill="none" stroke="${color}" stroke-width="2.5"/><path d="M${X(t)} 25V158" stroke="#92a48e" stroke-dasharray="4 4"/>${tangentLine}<circle cx="${X(t)}" cy="${Y(fn(t))}" r="4" fill="${color}"/><g font-size="10" fill="#697b65"><text x="3" y="${Y(hi-pad)+4}">${rnd(hi-pad)}</text><text x="3" y="${Y(lo+pad)+4}">${rnd(lo+pad)}</text><text x="24" y="${Y(0)+3}">0</text><text x="36" y="176">0</text><text x="248" y="176">${rnd(T)} s</text></g></svg><small>${caption}</small></div>`;
}
function readouts(items){return `<div class="readouts">${items.map(([name,val])=>`<div>${name}<b>${val}</b></div>`).join('')}</div>`}
function updateLab(){if(!$('#lab-display'))return;let display='';
 if(state.unit===1){const {x0,v0,a,t,duration:T}=lab,X=s=>x0+v0*s+.5*a*s*s,V=s=>v0+a*s;let positions=Array.from({length:101},(_,i)=>X(T*i/100)),xmin=Math.min(...positions)-2,xmax=Math.max(...positions)+2,px=v=>45+(v-xmin)/(xmax-xmin)*600,turn=a?-v0/a:-1,distance=turn>0&&turn<t?Math.abs(X(turn)-x0)+Math.abs(X(t)-X(turn)):Math.abs(X(t)-x0);
 display=`<div class="scene"><div class="row spread"><span class="eyebrow">01 / MOTION TRACK</span><span class="pill">+x →</span></div><svg viewBox="0 0 700 150" aria-label="${L('카트의 현재 위치','Current cart position')}"><path d="M45 95H645" stroke="#b9c9b2" stroke-width="2"/>${Array.from({length:5},(_,i)=>{let x=xmin+(xmax-xmin)*i/4;return `<path d="M${px(x)} 89V101" stroke="#9eae98"/><text x="${px(x)}" y="124" text-anchor="middle" font-size="12" fill="#6c7c65">${rnd(x)} m</text>`}).join('')}<rect x="${px(X(t))-23}" y="57" width="46" height="28" rx="6" fill="#24786b"/><circle cx="${px(X(t))-12}" cy="89" r="6" fill="#203333"/><circle cx="${px(X(t))+12}" cy="89" r="6" fill="#203333"/>${Math.abs(V(t))>.01?arrow(px(X(t)),42,px(X(t))+Math.sign(V(t))*Math.min(70,Math.abs(V(t))*6),42,'#188eb2','v'):''}</svg></div>${readouts([['t',`${t.toFixed(2)} s`],['x',`${rnd(X(t))} m`],['v',`${rnd(V(t))} m/s`],[L('변위 Δx','Displacement Δx'),`${rnd(X(t)-x0)} m`],[L('거리 d','Distance d'),`${rnd(distance)} m`]])}<div class="graphs">${chart('x–t','m',X,T,t,'#24786b',L('기울기 = 속도','Slope = velocity'),false,true)}${chart('v–t','m/s',V,T,t,'#188eb2',L('기울기 = 가속도 · 색칠 넓이 = 변위','Slope = acceleration · shaded area = displacement'),true,true)}${chart('a–t','m/s²',()=>a,T,t,'#a17bdb',L('색칠 넓이 = 속도 변화','Shaded area = velocity change'),true)}</div><div class="note">${Math.abs(V(t))<.01?L('이 순간 속도는 0이에요. 가속도가 남아 있다면 곧 방향이 바뀔 수 있어요.','Velocity is zero at this instant. A nonzero acceleration can still reverse the motion.'):V(t)*a>0?L('속도와 가속도의 부호가 같아요 → 속력이 증가해요.','Velocity and acceleration have matching signs → speed increases.'):V(t)*a<0?L('속도와 가속도의 부호가 반대예요 → 속력이 감소해요.','Velocity and acceleration have opposite signs → speed decreases.'):L('가속도가 0이에요 → 속도는 일정해요.','Acceleration is zero → velocity stays constant.')}</div>`;
 }else if(state.unit===2){let vx=lab.speed*cos(lab.angle),vy=lab.speed*sin(lab.angle),T=(vy+Math.sqrt(vy*vy+19.6*lab.height))/9.8;if(T<=1e-8){lab.duration=0;lab.t=0;lab.playing=false;$('#lab-display').innerHTML=`<div class="scene"><h3>${L('공이 이미 지면에 있어요.','The ball is already on the ground.')}</h3><p>${L('수평 발사를 보려면 초기 높이를 올려주세요. 같은 높이에서 발사하려면 발사각을 0°보다 크게 설정하세요.','Raise the initial height for horizontal launch, or choose an angle above 0° for a flight from ground level.')}</p></div>`;if($('#time')){$('#time').max=0;$('#time').value=0;$('#time-label').textContent='t = 0.00 s';$('#play').textContent=`▶ ${L('재생','Play')}`;}return;}lab.duration=T;lab.t=Math.min(lab.t,lab.duration);let t=lab.t,X=s=>vx*s,Y=s=>lab.height+vy*s-4.9*s*s,H=lab.height+vy*vy/19.6,R=vx*T,scale=Math.min(590/Math.max(R,1),205/Math.max(H,1)),px=x=>50+x*scale,py=y=>260-y*scale;
 display=`<div class="scene"><div class="row spread"><span class="eyebrow">02 / PROJECTILE MOTION</span><span class="pill">g = 9.8 m/s²</span></div><svg viewBox="0 0 700 310" role="img" aria-label="${L('포물선 궤적과 속도 벡터','Projectile trajectory and velocity vectors')}"><path d="M50 260H650M50 260V25" stroke="#a6b69e"/><polyline points="${Array.from({length:101},(_,i)=>`${px(X(T*i/100))},${py(Y(T*i/100))}`).join(' ')}" fill="none" stroke="#188eb2" stroke-width="2" stroke-dasharray="5 5"/><circle cx="${px(X(t))}" cy="${py(Y(t))}" r="8" fill="#188eb2"/>${arrow(px(X(t)),py(Y(t)),px(X(t))+vx*2,py(Y(t)),'#a17bdb','vₓ')}${Math.abs(vy-9.8*t)>.05?arrow(px(X(t)),py(Y(t)),px(X(t)),py(Y(t))-(vy-9.8*t)*2,'#24786b','vᵧ'):''}<text x="50" y="285" font-size="12">0</text><text x="${px(R)-15}" y="285" font-size="12">${rnd(R)} m</text><text x="10" y="${py(H)}" font-size="12">${rnd(H)} m</text><text x="550" y="25" font-size="12" fill="#d98735">aᵧ = −9.8 m/s²</text></svg></div>${readouts([['t',`${t.toFixed(2)} s`],['x',`${rnd(X(t))} m`],['y',`${rnd(Math.max(0,Y(t)))} m`],['vₓ',`${rnd(vx)} m/s`],['vᵧ',`${rnd(vy-9.8*t)} m/s`]])}<div class="graphs">${chart('x–t','m',X,T,t,'#188eb2',L('직선: 수평속도 일정','Linear: constant horizontal velocity'),false,true)}${chart('y–t','m',Y,T,t,'#24786b',L('기울기 = 수직속도','Slope = vertical velocity'),false,true)}${chart('vᵧ–t','m/s',s=>vy-9.8*s,T,t,'#d98735',L('넓이 = 수직 변위','Area = vertical displacement'),true)}${chart('vₓ–t','m/s',()=>vx,T,t,'#a17bdb',L('넓이 = 수평 변위','Area = horizontal displacement'),true)}${chart('aₓ–t','m/s²',()=>0,T,t,'#188eb2','aₓ = 0')}${chart('aᵧ–t','m/s²',()=>-9.8,T,t,'#d98735',L('최고점에도 −g','Still −g at the top'),true)}</div>`;
 }else {let W=lab.m2*9.8+lab.fa,N=W*cos(lab.theta),D=lab.m1*9.8-W*sin(lab.theta),limit=lab.mus*N,can=Math.abs(D)<=limit+1e-8,fr=lab.mode==='rest'?Math.min(Math.abs(D),limit):lab.muk*N,dir=lab.mode==='rest'?Math.sign(D):lab.mode==='up'?1:-1,acc=lab.mode==='rest'?(can?0:null):(D-dir*fr)/(lab.m1+lab.m2),T=acc===null?null:lab.m1*(9.8-acc),th=lab.theta*Math.PI/180,c=Math.cos(th),s=Math.sin(th),bx=410,by=150;
 display=`<div class="scene"><div class="row spread"><span class="eyebrow">03 / FORCE BALANCE</span><span class="pill">${L('m₂ 위쪽이 +','Uphill is + for m₂')}</span></div><svg viewBox="0 0 700 330" role="img" aria-label="${L('경사면 도르래의 실제 힘','Actual forces on an incline-pulley system')}"><path d="M210 ${by-200*s} L610 ${by+200*s} L210 310Z" fill="#f2f4ef" stroke="#50664d" stroke-width="2"/><circle cx="210" cy="${by-200*s-18}" r="19" fill="white" stroke="#50664d" stroke-width="2"/><path d="M191 ${by-200*s-18}V230M219 ${by-200*s-34}L${bx-25*c} ${by-25*s-30}" fill="none" stroke="#a17bdb" stroke-width="3"/><rect x="170" y="230" width="43" height="50" fill="#d5eaf0" stroke="#188eb2"/><text x="178" y="260">m₁</text><rect x="${bx-25}" y="${by-42}" width="50" height="42" transform="rotate(${lab.theta} ${bx} ${by})" fill="#d5eaf0" stroke="#188eb2"/><text x="${bx-5}" y="${by-10}">m₂</text>${arrow(bx,by-20,bx+s*70,by-20-c*70,'#188eb2','N')}${arrow(bx-8,by-20,bx-8,by+75,'#d98735','mg')}${arrow(bx+12,by-20,bx+12,by+35,'#c35e36','F_A')}${arrow(bx,by-20,bx-c*95,by-20-s*95,'#24786b','T')}${fr>.01?arrow(bx,by-20,bx+dir*c*75,by-20+dir*s*75,'#a17bdb','f'):''}${arrow(191,235,191,180,'#24786b','T')}${arrow(191,278,191,320,'#d98735','m₁g')}</svg></div>${readouts([['N',`${rnd(N)} N`],[L('필요 정지 마찰','Required static friction'),`${rnd(Math.abs(D))} N`],['μ_s N',`${rnd(limit)} N`],['μ_s,min',rnd(Math.abs(D)/N)],['a',acc===null?'—':`${rnd(acc)} m/s²`],['T',T===null?'—':`${rnd(T)} N`]])}<div class="formula">${lab.mode==='rest'?'|m₁g − (m₂g + F_A)sinθ| ≤ μ_sN':`a = [m₁g − (m₂g + F_A)sinθ ${dir>0?'−':'+'} μ_kN] / (m₁ + m₂)`}</div><div class="note">${lab.mode==='rest'?(can?L('정지를 유지할 수 있어요. 실제 마찰은 필요한 만큼만 작용해요.','Rest is possible. Actual friction adjusts to the required value.'):L('정지 마찰 한계를 넘었어요. 미끄러지는 상태를 선택하면 운동 마찰을 적용한 순간 가속도를 볼 수 있어요.','The static limit is exceeded. Select a sliding state to calculate instantaneous acceleration using kinetic friction.')):L('마찰은 미끄러지는 방향의 반대예요. 가속도가 음수여도 속도가 즉시 반대로 바뀌지는 않아요.','Friction opposes slipping. Negative acceleration does not instantly reverse velocity.')}</div>`;}
 $('#lab-display').innerHTML=display;if($('#time')){$('#time').max=lab.duration;$('#time').value=lab.t;$('#time-label').textContent=`t = ${lab.t.toFixed(2)} s`;$('#play').textContent=lab.playing?`Ⅱ ${L('일시정지','Pause')}`:`▶ ${L('재생','Play')}`;}
 $$('[data-graph-time]').forEach(el=>el.onclick=e=>{const r=el.getBoundingClientRect(),x=(e.clientX-r.left)/r.width*300;lab.t=Math.max(0,Math.min(lab.duration,(x-38)/235*Number(el.dataset.graphTime)));updateLab()});
}
function animate(time){if(lab.playing&&state.page==='lab'){if(lab.last)lab.t+=Math.min((time-lab.last)/1000,.06);if(lab.t>=lab.duration){lab.t=lab.duration;lab.playing=false}updateLab()}lab.last=time;requestAnimationFrame(animate)}requestAnimationFrame(animate);
function currentExam(){return EXAMS.find(e=>e.track===state.examUnit&&e.level===state.examLevel&&e.form===(state.examForm||1))}
function evidence(q,en=false){
 const f=q.figure;const loc=o=>en?o.en:tr(o),tag=(k,e)=>en?e:L(k,e);
 if(!f){return q.diagram?'<div class="casefig">'+mini(q.diagram,q.u,q.fig)+'</div>':''}
 if(f.shapes){let art=f.shapes.map(([k,a,b,c,d,e])=>k==='L'?'<line x1="'+a+'" y1="'+b+'" x2="'+c+'" y2="'+d+'" stroke="'+e+'" stroke-width="2"/>':k==='B'?'<rect x="'+a+'" y="'+b+'" width="'+c+'" height="'+d+'" fill="#d3edf1" stroke="#1684aa"/>':k==='C'?'<circle cx="'+a+'" cy="'+b+'" r="'+c+'" stroke="#384f50" fill="#e2eae8"/>':k==='T'?'<text x="'+a+'" y="'+b+'" text-anchor="middle">'+esc(c)+'</text>':'<polygon points="'+a.map(p=>p.join(',')).join(' ')+'" stroke="#1684aa" fill="#d3edf1"/>').join('');return '<figure class="casefig"><figcaption>'+loc(f.name)+'</figcaption><svg viewBox="38 0 205 123" role="img" aria-label="'+loc(f.name)+'">'+art+'</svg></figure>'}
 let cap=loc(f.name),label=tag('기준 측정 · 변형 전','Baseline measurements'),calc=n=>Number(n.toPrecision(4)),x=f.x,y=f.y;
 let table='<table><thead><tr><th>'+esc(f.X)+'</th><th>'+esc(f.Y)+'</th></tr></thead><tbody>'+x.map((n,i)=>'<tr><td>'+calc(n)+'</td><td>'+calc(y[i])+'</td></tr>').join('')+'</tbody></table>';
 let g='';if(f.type==='table')g=table;
 else if(f.type==='strip'){g='<div class="readstrip">'+x.map((n,i)=>'<div><small>'+esc(f.X)+'</small><b>'+calc(n)+'</b><small>'+esc(f.Y)+'</small><b>'+calc(y[i])+'</b></div>').join('')+'</div>'}
 else{let lo=Math.min(0,...y.map(v=>v-(f.err||0))),hi=Math.max(0,...y.map(v=>v+(f.err||0))),range=hi-lo||1;
 let px=v=>74+v/Math.max(...x)*232,py=v=>132-(v-lo)/range*98;
 g='<svg role="img" aria-label="'+esc(cap+': '+f.X+'; '+f.Y)+'" viewBox="0 0 365 165"><text x="8" y="16">'+esc(f.Y)+'</text><path d="M74 22V132H316" fill="none" stroke="#65746d"/><path stroke="#a4bdb7" stroke-dasharray="3 3" d="M74 '+py(0)+'H310"/><polyline fill="none" stroke="#1684aa" stroke-width="2.7" points="'+x.map((v,i)=>px(v)+','+py(y[i])).join(' ')+'"/>'+x.map((v,i)=>'<circle r="4" cx="'+px(v)+'" cy="'+py(y[i])+'" fill="#117099"/><text x="'+px(v)+'" y="150" text-anchor="middle">'+calc(v)+'</text>'+(f.err?'<path stroke="#aa582d" d="M'+px(v)+' '+py(y[i]+f.err)+'V'+py(y[i]-f.err)+'"/>':'')).join('')+'<text x="67" y="39" text-anchor="end">'+calc(hi)+'</text><text x="67" y="133" text-anchor="end">'+calc(lo)+'</text><text x="312" y="163" text-anchor="end">'+esc(f.X)+'</text></svg>'}
 let machine='';if(q.pulley&&q.parts&&q.family>=50&&q.family<60){let fnum=q.family-50;
 if([4,7].includes(fnum))machine=mini('incline');else if([3,6,8].includes(fnum))machine='<svg viewBox="0 0 250 130" role="img" aria-label="Cart and hanger"><path d="M10 70H166V120" fill="none" stroke="#567"/><circle cx="167" cy="57" r="10" fill="#dae6eb" stroke="#567"/><path d="M57 47H167Q177 48 177 57V92" fill="none" stroke="#7759a1" stroke-width="2"/><rect x="30" y="43" width="44" height="25" rx="3" fill="#c6e5eb" stroke="#1684aa"/><rect x="166" y="91" width="22" height="25" fill="#c6e5eb" stroke="#1684aa"/><text x="43" y="61">M</text><text x="171" y="109">m</text></svg>';else machine=mini('pulley');
 }
 return '<figure class="casefig"><figcaption>'+esc(cap)+' · '+label+'</figcaption>'+(machine?'<div class="case-machine">'+machine+'</div>':'')+g+'</figure>'
}

function qgroup(q){return q.id.startsWith('N')?'data':q.id.startsWith('M-')||q.id.startsWith('I')?'reason':'apply'}
function filtered(){return (state.kind==='MCQ'?BANK:FRQS).filter(q=>q.u===state.unit&&q.level===state.level&&(!state.pulleyOnly||state.unit!==3||q.pulley)&&(!state.wrong||state.answers[q.id]?.graded&&!state.answers[q.id]?.correct)&&(!state.focusSkill||qgroup(q)===state.focusSkill)&&(!state.search||tr(q.stem).toLowerCase().includes(state.search.toLowerCase())||q.id.toLowerCase().includes(state.search.toLowerCase()))).sort((a,b)=>{const key=q=>(q.id.startsWith('M-')?0:q.id.startsWith('I')?1:q.id.startsWith('U')?2:3)*1000+(q.variant||0)*100+q.family;return key(a)-key(b)})}
function practice(){let list=filtered();state.index=Math.max(0,Math.min(state.index,list.length-1));let q=list[state.index];return `<div class="eyebrow">PRACTICE / LEARN BY DOING</div><h1>${L('생각하고, 풀고, 다시 이해해요.','Think it through. Make it click.')}</h1><p class="muted">${L('A 기초 → F 심화 · 그래프, 실험, 설명, 유도 · 기록은 이 기기에 저장됩니다.','A foundations → F advanced · Graphs, experiments, explanations and derivations · Progress saved locally')}</p>${unitTabs(state.unit)}<div class="filter"><select id="q-kind" aria-label="Question type"><option ${state.kind==='MCQ'?'selected':''}>MCQ</option><option ${state.kind==='FRQ'?'selected':''}>FRQ</option></select><select id="q-level" aria-label="Difficulty">${LEVELS.map((l,i)=>`<option value="${l}" ${state.level===l?'selected':''}>${l} · ${tr(LEVEL_NAMES[i])}</option>`).join('')}</select>${state.unit===3?`<label><input id="pulley-only" type="checkbox" ${state.pulleyOnly?'checked':''}> ${L('도르래 집중 연습','Pulley focus')}</label>`:''}<select id="focus-skill" aria-label="${L('문제 유형','Problem type')}">${[['',L('모든 유형','All problem types')],['reason',L('개념 판단 · 장치','Concepts & apparatus')],['data',L('자료 해석 · 실험','Data & experiments')],['apply',L('운동 · 힘 계산','Motion & force calculations')]].map(([v,n])=>`<option value="${v}" ${(state.focusSkill||'')===v?'selected':''}>${n}</option>`).join('')}</select><input id="q-search" placeholder="${L('문제 내용 검색','Search questions')}" value="${esc(state.search)}"><label><input type="checkbox" id="wrong-only" ${state.wrong?'checked':''} ${state.kind==='FRQ'?'disabled':''}> ${L('MCQ 오답만','Incorrect MCQ only')}</label><span class="muted">${list.length} ${L('문항','questions')}</span></div>${q?`<div class="question"><div class="row spread"><span class="q-top">${q.id} · ${state.index+1} / ${list.length}</span><select id="q-jump" aria-label="${L('문제로 이동','Jump to question')}">${list.map((qq,i)=>`<option value="${i}" ${i===state.index?'selected':''}>${i+1}. ${qq.id} · ${esc(tr(qq.figure?.name||qq.stem).slice(0,40))}</option>`).join('')}</select></div><div class="card ${state.kind==='FRQ'?'frq':''}"><p class="q-prompt">${esc(tr(q.stem))}</p>${evidence(q)}${state.kind==='MCQ'?mcq(q):frqBody(q)}</div><div class="q-nav"><button id="prev-q" ${state.index===0?'disabled':''}>← ${L('이전','Previous')}</button><span class="muted">${state.kind==='MCQ'?L('답을 고른 뒤 채점해요.','Choose an answer, then check.'):L('풀이를 쓰고 모범 답안과 비교해요.','Write your reasoning, then compare with the model.')}</span><button id="next-q" ${state.index===list.length-1?'disabled':''}>${L('다음','Next')} →</button></div></div>`:`<div class="empty">${L('이 조건에 맞는 문항이 없어요. 필터를 바꿔보세요.','No questions match. Try changing the filters.')}</div>`}`}
function mcq(q){let r=state.answers[q.id]||{};return `<div class="options">${q.options.map((o,i)=>`<button class="option ${r.selected===i?'selected':''} ${r.graded&&q.answer===i?'correct':''} ${r.graded&&r.selected===i&&i!==q.answer?'wrong':''}" data-answer="${i}" aria-pressed="${r.selected===i}"><b>${'ABCD'[i]}</b><span>${esc(tr(o))}</span></button>`).join('')}</div><div class="row"><button id="grade" class="primary" ${r.selected===undefined||r.graded?'disabled':''}>${L('정답 확인','Check answer')}</button><button id="retry">${L('다시 풀기','Try again')}</button></div>${r.graded?`<div class="feedback ${r.correct?'':'wrong'}" role="status"><h3>${r.correct?L('정답이에요 ✓','Correct ✓'):L('한 번 더 살펴봐요','Let’s look again')} · ${L('정답','Answer')} ${'ABCD'[q.answer]}</h3><p>${esc(tr(q.explain))}</p><small>${L('틀린 선택지는 방향·성분·넓이의 부호 또는 적용 조건을 놓쳤는지 확인하세요.','For other choices, check direction, components, signed area, and the stated assumptions.')}</small></div>`:''}`}
function frqBody(q){return `${q.parts.map((p,i)=>`<div class="part"><p><b>${String.fromCharCode(97+i)}.</b> ${esc(tr(p.prompt))} <b>(${p.points} ${L('점','pt')})</b></p><textarea data-note="${q.id}-${i}" aria-label="${q.id} part ${i+1}" placeholder="${L('식, 근거, 단위를 포함해 풀이를 적어보세요. 그림은 종이에 그려도 좋아요.','Write equations, reasoning, and units. You can draw diagrams on paper.')}" >${esc(state.notes[q.id+'-'+i]||'')}</textarea></div>`).join('')}<details><summary>${L('모범 답안과 부분점수 기준','Model answer and scoring guide')}</summary>${q.parts.map((p,i)=>`<p><b>${String.fromCharCode(97+i)}. (${p.points} pt)</b><br>${esc(tr(p.answer))}</p>`).join('')}<small>${L('FRQ는 자동 채점하지 않아요. 식 설정·계산·단위와 근거를 모범 답안과 비교해 자기 채점하세요.','FRQ responses are not automatically graded. Self-assess equations, calculations, units, and reasoning against the model.')}</small></details>`}
function examPage(){const L=(_ko,en)=>en,tr=o=>typeof o==='string'?o:o?.en||'';let ex=currentExam();let unit=UNITS[ex.u-1],results=state.examSubmitted[ex.id];return `<div class="eyebrow">ASSESS / MOCK EXAMS</div><h1>${L('익숙한 시험지, 새로운 도전.','A familiar format. A fresh challenge.')}</h1><p class="muted">${L('첨부 시험의 구성: 2페이지 · 4 MCQ + 3 FRQ · 총 15점. 정답과 해설은 별도로 확인하세요.','The supplied format: 2 pages · 4 MCQ + 3 FRQ · 15 points. Answers and explanations are separate.')}</p><div class="filter"><select id="exam-unit" aria-label="Exam unit">${[...UNITS,{id:4,title:{en:'Pulley Focus'}}].map(u=>`<option value="${u.id}" ${ex.track===u.id?'selected':''}>Unit ${u.id} · ${tr(u.title)}</option>`).join('')}</select><select id="exam-form" aria-label="Exam form">${[1,2].map(f=>`<option value="${f}" ${ex.form===f?'selected':''}>Form ${f}</option>`).join('')}</select><select id="exam-level" aria-label="Exam difficulty">${LEVELS.map((v,i)=>`<option ${ex.level===v?'selected':''}>${v}</option>`).join('')}</select><span class="muted">${tr(LEVEL_NAMES[LEVELS.indexOf(ex.level)])}</span></div><div class="row exam-toolbar"><a class="primary" style="padding:9px 16px;border-radius:8px;text-decoration:none" href="exams/${ex.id}.pdf" download>${L('원본 형식 시험지 PDF · 영어','Download two-page exam · English')} ↓</a><button id="print-exam">${L('영어 시험지 인쇄','Print exam · English')}</button><button id="grade-exam">${L('MCQ 채점 · FRQ 채점 기준','Grade MCQ · FRQ scoring guide')}</button><button id="reset-exam">${L('시험 답안 초기화','Reset exam answers')}</button></div><div class="exam-sheet"><div class="exam-name"><span>Name: _______________________________________</span><span>Date: __________ &nbsp; Period: _______</span></div><div class="integrity"><b>Integrity Statement:</b><br>I acknowledge that I will complete this practice assessment using only my own work. Show all reasoning for free-response questions.</div><h2>Unit ${ex.u} Quiz 1 - ${unit.title.en}</h2><p class="exam-sub">Mock Exam ${ex.level} · Form ${ex.form}${ex.track===4?' · Pulley Focus':''}: ${LEVEL_NAMES[LEVELS.indexOf(ex.level)].en}</p><hr><div class="row"><h3>Multiple Choice Questions:</h3><span>${L('가장 알맞은 답을 고르세요. (각 1점)','Select the best answer. (1 point each)')}</span></div>${ex.questions.map((q,i)=>`<div class="exam-question"><p><b>${i+1}.</b> ${esc(tr(q.stem))}</p>${evidence(q,true)}<div class="exam-options">${q.options.map((o,j)=>`<label><input type="radio" name="${ex.id}-q${i}" data-exam-answer="${i}" value="${j}" ${state.examAnswers[ex.id]?.[i]===j?'checked':''}> (${'ABCD'[j]}) &nbsp;${esc(tr(o))}</label>`).join('')}</div></div>`).join('')}<div class="exam-foot"><span>Unit ${ex.u} - ${unit.title.en} | g = 9.8 m/s²</span><span>Exam ${ex.level} · Page 1 of 2</span></div></div><div class="exam-sheet"><div class="exam-name"><span>Name: _______________________________________</span><span>Mock Exam ${ex.level} · Form ${ex.form}${ex.track===4?' · Pulley Focus':''}</span></div><h3 style="margin-top:15px">Free Response Questions:</h3><p style="font-size:12px">${L('모든 문항에 답하고 풀이와 답을 명확히 표시하세요.','Answer all parts. Show your work and clearly indicate your answers.')}</p>${ex.frqs.map((q,i)=>`<div class="exam-question"><p><b>${i+5}.</b> ${esc(tr(q.stem))}</p>${q.parts.map((p,j)=>`<p style="font-size:12px;margin-top:12px"><b>${q.parts.length>1?String.fromCharCode(97+j)+'. ':''}</b>${esc(tr(p.prompt))} <b>(${p.points} pt)</b></p>${i===0&&j===0?`<div style="display:flex;justify-content:center">${evidence(q,true)}</div>`:`<textarea data-note="${ex.id}-${i}-${j}" aria-label="Question ${i+5}, part ${j+1}" style="height:${i===2?90:50}px">${esc(state.notes[`${ex.id}-${i}-${j}`]||'')}</textarea>`}`).join('')}</div>`).join('')}<div class="exam-foot"><span>Unit ${ex.u} - ${unit.title.en} | g = 9.8 m/s²</span><span>Exam ${ex.level} · Page 2 of 2</span></div></div>${results?`<div class="exam-results card"><h2>${L('MCQ 결과','MCQ score')}: ${ex.questions.filter((q,i)=>state.examAnswers[ex.id]?.[i]===q.answer).length} / 4</h2>${ex.questions.map((q,i)=>`<p><b>${i+1}. ${'ABCD'[q.answer]}</b> · ${esc(tr(q.explain))}</p>`).join('')}<h3>${L('FRQ 모범 답안 · 11점 자기 채점','FRQ model answers · self-assess 11 points')}</h3>${ex.frqs.map((q,i)=>`<p><b>${i+5}.</b></p>${q.parts.map((p,j)=>`<p><b>${String.fromCharCode(97+j)}. (${p.points} pt)</b> ${esc(tr(p.answer))}</p>`).join('')}`).join('')}</div>`:''}`}
function render(){document.documentElement.lang=state.lang;$('#app').innerHTML=header()+`<main class="wrap">${({home,learn,lab:labPage,practice,exam:examPage}[state.page])()}<footer class="footer"><div class="row spread"><span>physics, step by step · ${L('직접 보고 이해하는 물리','Make physics visible')}</span><span>${L('제공한 학습 자료 범위 · 학습용 자체 제작 문제 · 공식 AP 시험 아님','Based on supplied learning materials · Original practice questions · Not an official AP exam')}</span></div></footer></main>`;bind();if(state.page==='lab')updateLab()}
function bind(){
 if($('#direct-pulley'))$('#direct-pulley').onclick=()=>{state.unit=3;state.pulleyOnly=true;state.focusSkill="";state.index=0;state.search='';state.wrong=false;nav('practice')};
 if($('#direct-papers'))$('#direct-papers').onclick=()=>{state.examUnit=4;state.examForm=1;nav('exam')};
 $$('[data-nav]').forEach(b=>b.onclick=()=>nav(b.dataset.nav));$('#language').onclick=()=>{state.lang=state.lang==='ko'?'en':'ko';save();render()};
 $$('[data-open-unit]').forEach(b=>{b.onclick=()=>{state.unit=+b.dataset.openUnit;state.lesson=LESSONS.find(l=>l.u===state.unit).id;nav('learn')};b.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();b.click()}}});
 $$('[data-unit]').forEach(b=>b.onclick=()=>{state.unit=+b.dataset.unit;state.index=0;lab.t=0;render()});
 $$('[data-chapter-done]').forEach(b=>b.onclick=()=>{const list=LESSONS.filter(l=>l.u===state.unit),c=READING_CHAPTERS.filter(c=>c.u===state.unit)[+b.dataset.chapterDone],done=c.items.every(j=>state.done[list[j].id]);c.items.forEach(j=>state.done[list[j].id]=!done);save();b.className=!done?'active':'primary';b.textContent=!done?L('이 부분 학습 완료 ✓','Section completed ✓'):L('이 부분 이해했어요 ✓','Mark section understood ✓')});
 $$('[data-lesson]').forEach(b=>b.onclick=()=>{state.lesson=+b.dataset.lesson;render()});
 if($('#mark-done'))$('#mark-done').onclick=()=>{state.done[state.lesson]=!state.done[state.lesson];save();render()};
 if($('#next-lesson'))$('#next-lesson').onclick=()=>{const i=LESSONS.findIndex(l=>l.id===state.lesson),next=LESSONS[(i+1)%LESSONS.length];state.lesson=next.id;state.unit=next.u;render();window.scrollTo(0,0)};
 $$('[data-check]').forEach(c=>c.onchange=()=>{state.checks[c.dataset.check]=c.checked;save();$('#check-count').textContent=`${Object.values(state.checks).filter(Boolean).length}/7`});if($('#reset-checks'))$('#reset-checks').onclick=()=>{state.checks={};save();render()};
 $$('[data-param]').forEach(r=>r.oninput=()=>{lab[r.id]=+r.value;lab.t=0;lab.playing=false;$('#'+r.id+'-out').textContent=r.value+(r.id==='angle'||r.id==='theta'?' °':'');updateLab()});
 if($('#preset'))$('#preset').onchange=e=>{const p={turn:{x0:0,v0:4,a:-1,duration:8},constant:{x0:-5,v0:2,a:0,duration:8},speedup:{x0:0,v0:-2,a:-1,duration:8},fall:{x0:0,v0:9.8,a:-9.8,duration:2}}[e.target.value];Object.assign(lab,p,{t:0,duration1:p.duration});['x0','v0','a'].forEach(id=>{$('#'+id).value=lab[id];$('#'+id+'-out').textContent=lab[id]});updateLab()};
 if($('#mode')){$('#mode').value=lab.mode;$('#mode').onchange=e=>{lab.mode=e.target.value;updateLab()}}
 if($('#play'))$('#play').onclick=()=>{if(lab.t>=lab.duration)lab.t=0;lab.playing=!lab.playing;lab.last=0;updateLab()};if($('#reset-time'))$('#reset-time').onclick=()=>{lab.t=0;lab.playing=false;updateLab()};if($('#time'))$('#time').oninput=e=>{lab.t=+e.target.value;lab.playing=false;updateLab()};
 if($('#focus-skill'))$('#focus-skill').onchange=e=>{state.focusSkill=e.target.value;state.index=0;render()};if($('#pulley-only'))$('#pulley-only').onchange=e=>{state.pulleyOnly=e.target.checked;state.index=0;render()};if($('#q-kind'))$('#q-kind').onchange=e=>{state.kind=e.target.value;state.wrong=false;state.index=0;render()};if($('#q-level'))$('#q-level').onchange=e=>{state.level=e.target.value;state.index=0;render()};if($('#q-search'))$('#q-search').onchange=e=>{state.search=e.target.value;state.index=0;render()};if($('#wrong-only'))$('#wrong-only').onchange=e=>{state.wrong=e.target.checked;state.index=0;render()};if($('#q-jump'))$('#q-jump').onchange=e=>{state.index=+e.target.value;render()};
 $$('[data-answer]').forEach(b=>b.onclick=()=>{const q=filtered()[state.index];if(state.answers[q.id]?.graded)return;state.answers[q.id]={selected:+b.dataset.answer};save();render()});
 if($('#grade'))$('#grade').onclick=()=>{const q=filtered()[state.index],r=state.answers[q.id];r.graded=true;r.correct=r.selected===q.answer;save();render()};if($('#retry'))$('#retry').onclick=()=>{const q=filtered()[state.index];delete state.answers[q.id];save();render()};if($('#next-q'))$('#next-q').onclick=()=>{state.index++;render()};if($('#prev-q'))$('#prev-q').onclick=()=>{state.index--;render()};
 $$('[data-note]').forEach(t=>t.oninput=()=>{state.notes[t.dataset.note]=t.value;save()});
 if($('#exam-form'))$('#exam-form').onchange=e=>{state.examForm=+e.target.value;render()};if($('#exam-unit'))$('#exam-unit').onchange=e=>{state.examUnit=+e.target.value;render()};if($('#exam-level'))$('#exam-level').onchange=e=>{state.examLevel=e.target.value;render()};
 $$('[data-exam-answer]').forEach(r=>r.onchange=()=>{let id=currentExam().id;state.examAnswers[id]??={};state.examAnswers[id][r.dataset.examAnswer]=+r.value;save()});
 if($('#grade-exam'))$('#grade-exam').onclick=()=>{state.examSubmitted[currentExam().id]=true;render();$('.exam-results').scrollIntoView({behavior:'smooth'})};if($('#print-exam'))$('#print-exam').onclick=()=>window.print();if($('#reset-exam'))$('#reset-exam').onclick=()=>{let id=currentExam().id;delete state.examAnswers[id];delete state.examSubmitted[id];Object.keys(state.notes).filter(k=>k.startsWith(id)).forEach(k=>delete state.notes[k]);save();render()};
}
render();





